import numpy as np,pandas as pd,pickle,os
from sklearn.model_selection import KFold,GroupKFold
from sklearn.metrics import mean_absolute_error,mean_squared_error,r2_score
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,HistGradientBoostingRegressor
from catboost import CatBoostRegressor
from pymatgen.core import Composition
X,tr,po=pickle.load(open('/tmp/features.pkl','rb'));n=len(tr);y=tr.dn.to_numpy();groups=np.array([Composition(x).reduced_formula for x in tr.formula]);cat=list(X.select_dtypes('object').columns)
# feature sets
sets={'comp':[c for c in X if c.startswith(('comp_','frac_','density_'))], 'base':[c for c in X if not c.startswith(('bond','element','local'))], 'all':list(X.columns),'geom':[c for c in X if not c.startswith('element')]}
folds=list(GroupKFold(5,shuffle=True,random_state=311).split(X[:n],y,groups=groups))
res=[];results={};out=[]
for subset in ['base','geom','all']:
 cols=sets[subset]
 for method in ['cat4','cat6','extra','rf']:
  for trans in ['raw','log']:
   yy=y if trans=='raw' else np.log1p(y/.05)
   x=X[cols].copy();cats=[c for c in cat if c in cols]
   if method in ['extra','rf']:
    x=pd.get_dummies(x,columns=cats).astype(float)
   else:
    x[cats]=x[cats].astype(str)
   oof=np.zeros(n);poolpred=[]
   for j,(ii,jj) in enumerate(folds+[ (np.arange(n),np.array([],int)) ]):
    if method.startswith('cat'):
     model=CatBoostRegressor(iterations=800,depth=int(method[-1]),learning_rate=.035,l2_leaf_reg=5,verbose=False,loss_function='RMSE',thread_count=3,random_seed=42+j,cat_features=cats)
    elif method=='extra':model=ExtraTreesRegressor(n_estimators=500,min_samples_leaf=2,max_features=.7,n_jobs=3,random_state=42+j)
    else:model=RandomForestRegressor(n_estimators=500,min_samples_leaf=1,max_features=.7,n_jobs=3,random_state=42+j)
    model.fit(x.iloc[ii],yy[ii]);pred=model.predict(x.iloc[jj]) if len(jj) else None
    inv=lambda p: np.maximum(0,p if trans=='raw' else np.expm1(p)*.05)
    if len(jj):oof[jj]=inv(pred)
    else:
     p=inv(model.predict(x.iloc[n:]));imp=pd.Series(model.feature_importances_,index=x.columns).sort_values(ascending=False)
     key=f'{subset}_{method}_{trans}';results[key]={'oof':oof,'pool':p,'importance':imp}
     res.append((key,mean_absolute_error(y,oof),np.sqrt(mean_squared_error(y,oof)),r2_score(y,oof)))
     print(res[-1],flush=True)
     ranked=np.argsort(p)[::-1][:15]
     print([(po.candidate_id.iloc[i],po.formula.iloc[i],round(p[i],3)) for i in ranked],flush=True)
     print('Importance',imp.head(15).round(4).to_dict(),flush=True)
     pickle.dump(results,open('/tmp/results.pkl','wb'))
print(pd.DataFrame(res,columns=['name','MAE','RMSE','r2']).sort_values('RMSE').to_string(index=False))
pred=pd.DataFrame({k:v['pool'] for k,v in results.items()});pred['candidate_id']=po.candidate_id;pred['formula']=po.formula;pred.to_csv('/tmp/predictions.csv',index=False)

